        baselines.set(row.pid, { at, cpuTimeMs: row.cpuTimeMs, command: row.command });
        samples.set(row.pid, {
          pid: row.pid,
          ppid: row.ppid,
          rssKb: row.rssKb,
          cpuPercent,
          command: row.command,
        });
      }
      for (const [pid, baseline] of baselines) {
        if (!samples.has(pid) && at - baseline.at > 60000) baselines.delete(pid);
      }
      return samples;
    },
  };
