function parseCpuTime(text: string): number | undefined {
  let clock = text.trim();
  let days = 0;
  const separator = clock.indexOf("-");
  if (separator > 0) {
    days = Number(clock.slice(0, separator));
    if (!nonnegativeInteger(days)) return undefined;
    clock = clock.slice(separator + 1);
