  let initial: ProcessTreeOwnershipResolution;
  if (process.platform === "win32" && snapshot != null &&
    child.exitCode === null && child.signalCode === null) {
    initial = {
      childStillOwned: unavailable || identities.some((identity) => identity.pid === child.pid),
