  const waitOptions = unavailable ? { ...options, unverifiedRootOnly: true } : options;
  const hasTargets = initial.currentIdentities.length > 0 ||
    (!unavailable && initial.childStillOwned);
  return await waitForProcessTreeTermination(
    child, waitOptions, initial, hasTargets, terminateProcessTree,
  );
